const p = $('Params').first().json;
const cur = ($input.first().json.body && $input.first().json.body.keys) || [];
const byId = {}; for (const k of cur) { byId[k.key_id] = k; }
const out = []; const plan = [];
for (const w of p.keys) {
  const k = byId[w.key_id];
  if (!k || k.is_archived) { plan.push({ key_id: w.key_id, skipped: 'missing or archived' }); continue; }
  const o = { key_id: w.key_id }; const did = [];
  if (!k.description || !String(k.description).trim()) { o.description = w.description; did.push('description'); }
  const have = k.tags || []; const add = p.tags.filter(function (t) { return have.indexOf(t) < 0; });
  if (add.length) { o.tags = add; o.merge_tags = true; did.push('tags:' + add.join(',')); }
  if (did.length) { out.push(o); }
  plan.push({ key_id: w.key_id, name: k.key_name && k.key_name.web, did: did, old_tags: have, had_screens: (k.screenshots || []).length });
}
return [{ json: { project_id: p.project_id, body: { keys: out }, count: out.length, plan: plan } }];

const p = $('Params').first().json; const b = $('Build').first().json;
const ks = ($input.first().json.body && $input.first().json.body.keys) || [];
const res = ks.map(function (k) { const w = p.keys.find(function (x) { return x.key_id === k.key_id; }) || {}; return { key_id: k.key_id, name: k.key_name && k.key_name.web, tags: k.tags, description_ok: k.description === w.description, has_all_tags: p.tags.every(function (t) { return (k.tags || []).indexOf(t) >= 0; }), kept_push_tags: ['main','to_review'].every(function (t) { return (k.tags || []).indexOf(t) >= 0; }) }; });
return [{ json: { put_status: $('Write').first().json.statusCode, put_errors: $('Write').first().json.body && $('Write').first().json.body.errors, plan: b.plan, readback: res } }];
